/**
 * Written into the corpus by the live-edit eval AFTER indexing, to stand in
 * for a file the agent created during a session. Nothing imports it.
 */

export interface QuarantinedSpanLedger {
	spanId: string;
	quarantinedAtMs: number;
}

/** Records a span the retriever should not surface again this session. */
export function quarantineRetrievalSpan(ledger: QuarantinedSpanLedger[], spanId: string): QuarantinedSpanLedger[] {
	return [...ledger, { spanId, quarantinedAtMs: Date.now() }];
}

/**
 * Written into the corpus by the live-edit eval AFTER indexing, to stand in
 * for an edit the agent made to an existing file during a session.
 */

/** Threshold above which a fused candidate is considered stale. */
export const STALE_CANDIDATE_THRESHOLD_MS = 900_000;

export function isCandidateStale(observedAtMs: number, nowMs: number): boolean {
	return nowMs - observedAtMs > STALE_CANDIDATE_THRESHOLD_MS;
}
